mapper.sql:
id=#{command.id} AND space_id=#{command.spaceId} AND workspace_id=#{command.workspaceId} AND environment_id=#{command.environmentId}
        AND actor_id=#{command.actorId} AND owner_id=#{command.ownerId} AND generation=#{command.generation} AND fence=#{command.fence}
        AND lease_until>clock_timestamp() AND deadline_at>clock_timestamp()

mapper.update:
UPDATE pf.workspace_environment_use SET exec_id=#{execId},version=version+1
        WHERE id=#{command.id} AND space_id=#{command.spaceId} AND workspace_id=#{command.workspaceId} AND environment_id=#{command.environmentId}
        AND actor_id=#{command.actorId} AND owner_id=#{command.ownerId} AND runner_instance_id=#{runnerId} AND file_execution_mode='TRUSTED_HELPER'
        AND status='CLAIMED' AND exec_id IS NULL AND generation=#{command.generation} AND fence=#{command.fence}
        AND execute_until>clock_timestamp() AND lease_until>clock_timestamp() AND NOT cancel_requested

UPDATE pf.workspace_environment_use SET status=#{state},result_state=#{outcome},error_code=#{error},version=version+1
        WHERE id=#{command.id} AND owner_id=#{command.ownerId} AND space_id=#{command.spaceId} AND workspace_id=#{command.workspaceId}
        AND environment_id=#{command.environmentId} AND generation=#{command.generation} AND fence=#{command.fence}
        AND status IN('CLAIMED','RUNNING','UNKNOWN') AND EXISTS(SELECT 1 FROM pf.workspace_environment_use_result r WHERE r.use_id=#{command.id})

mapper.select:
SELECT EXISTS(SELECT 1 FROM pf.workspace_environment_use u WHERE u.id=#{id}
        AND EXISTS(SELECT 1 FROM pf.workspace_runner_instance i WHERE i.id=#{runnerId} AND NOT EXISTS(SELECT 1 FROM pf.workspace_runner_stop_proof p WHERE p.runner_instance_id=i.id))
        AND(u.runner_instance_id=#{runnerId} OR EXISTS(SELECT 1 FROM pf.workspace_runner_stop_proof p WHERE p.runner_instance_id=u.runner_instance_id)))

mapper.update:
UPDATE pf.workspace_environment SET state='STOPPED',operation_id=#{operationId},fence=#{fence},version=version+1,error_code=#{error},
        last_activity_at=clock_timestamp(),updated_at=clock_timestamp() WHERE id=#{command.environmentId} AND space_id=#{command.spaceId} AND workspace_id=#{command.workspaceId}
        AND generation=#{command.generation} AND fence=#{command.fence}

UPDATE pf.workspace_environment_use SET status='STOPPED',result_state=#{outcome},error_code=#{error},stop_operation_id=#{operationId},version=version+1
        WHERE id=#{command.id} AND space_id=#{command.spaceId} AND workspace_id=#{command.workspaceId} AND environment_id=#{command.environmentId}
        AND generation=#{command.generation} AND fence=#{command.fence} AND status IN('CLAIMED','RUNNING','UNKNOWN')
